def calc(lang):
    rows = [('Café coado (200 ml)', 'Drip coffee (200 ml)', '95'), ('Espresso (1 dose)', 'Espresso (1 shot)', '65'), ('Chá preto (200 ml)', 'Black tea (200 ml)', '50'), ('Matcha (2 g)', 'Matcha (2 g)', '60'),
            ('Chá verde (200 ml)', 'Green tea (200 ml)', '30'), ('Oolong (200 ml)', 'Oolong (200 ml)', '40'), ('Chimarrão (cuia, sessão)', 'Mate (gourd, session)', '80–150'), ('Refrigerante de cola (350 ml)', 'Cola (350 ml)', '35'),
            ('Energético (250 ml)', 'Energy drink (250 ml)', '80'), ('Chocolate amargo (30 g)', 'Dark chocolate (30 g)', '20')]
    head = f'<tr><th>{tr(("Bebida", "Drink"), lang)}</th><th>{tr(("mg (média)", "mg (average)"), lang)}</th><th>{tr(("Quantas hoje?", "How many today?"), lang)}</th><th>{tr(("Total", "Total"), lang)}</th></tr>'
    body = ''.join(f'<tr><td>{esc(a if lang == "pt" else b)}</td><td>{c}</td><td style="width:30mm"></td><td style="width:25mm"></td></tr>' for a, b, c in rows)
    body += f'<tr><td><b>{tr(("Soma do dia", "Daily total"), lang)}</b></td><td></td><td></td><td style="border-bottom:.8pt solid var(--gold3)"></td></tr>'
    return f'<table class="data">{head}{body}</table>'


